engine.polishFragment:
async function polishFragment(input, providers) {
  var fragment = String((input && input.fragment) || "");
  var ctx = String((input && input.context) || "");
  var mode = String((input && input.mode) || "regen");
  if (!fragment.trim()) throw new Error("Nothing highlighted.");

  var MODES = {
    regen:    "Rewrite it: same meaning, better wording.",
    human:    "Rewrite it so it sounds natural and human — plain, direct, unstuffy. Strip legalese, hedging and throat-clearing.",
    shorten:  "Make it materially shorter. Cut redundancy, doublets and filler while keeping every substantive point.",
    lengthen: "Expand it with more precision and detail, making implicit points explicit. Do NOT invent new facts, obligations, conditions or parties.",
    firmer:   "Make it firmer and more direct. Remove softeners and equivocation. Professional, not aggressive.",
    softer:   "Make it more conciliatory and diplomatic while leaving the substance unchanged.",
  };
  var styleLine = MODES[mode] || MODES.regen;

  var prompt =
    "You are editing ONE highlighted fragment inside a larger passage. Rewrite ONLY the fragment.\n\n" +
    styleLine + "\n" +
    "PRESERVE MEANING EXACTLY — no obligation, condition, exception, amount, date, defined term or " +
    "cross-reference may change, appear or disappear.\n" +
    "It must read naturally where it sits: match the surrounding tense, person, register and punctuation, " +
    "and do not repeat words that immediately precede or follow it.\n" +
    "Return ONLY the replacement text — no quotes, no preamble, no explanation, no trailing period unless " +
    "the fragment itself ended with one.\n\n" +
    "FULL PASSAGE (context only — do NOT return it):\n\"\"\"\n" + ctx + "\n\"\"\"\n\n" +
    "HIGHLIGHTED FRAGMENT TO REWRITE:\n\"\"\"\n" + fragment + "\n\"\"\"";

  var out = await providers.ai.complete(prompt, {
    thinkingBudget: 256,
    signal: input && input.signal,
  });
  return String(out || "").trim().replace(/^["“']+/, "").replace(/["”']+$/, "");
}

engine.polishAnalyze:
async function polishAnalyze(input, providers) {
  var original = String((input && input.text) || "");
  var instruction = String((input && input.instruction) || "").trim();
  // Surrounding document text, used only by the vocabulary-drift check.
  var docText = String((input && input.docText) || "");
  // Phrases the user marked as untouchable — negotiated wording that must
  // survive verbatim while everything around it is improved.
  var locked = (input && Array.isArray(input.locked) ? input.locked : [])
    .map(function (s) { return String(s || "").trim(); })
    .filter(Boolean);
  if (!original.trim()) {
    throw new Error("Nothing selected to polish.");
  }

  // ── Deterministic preservation check ─────────────────────────────────
  // Facts that MUST survive a meaning-preserving rewrite. Deliberately
  // high-signal only — exact tokens plus one structural test — because a
  // noisy guard trains people to ignore it.
  function _collect(s) {
    var out = [];
    function add(re, capIdx) {
      var m;
      re.lastIndex = 0;
      while ((m = re.exec(s)) !== null) {
        var v = capIdx != null ? m[capIdx] : m[0];
        if (v && String(v).trim()) out.push(String(v).trim());
        if (m.index === re.lastIndex) re.lastIndex++;
      }
    }
    // Proper thousands grouping — [\d,]+ would swallow a trailing comma
    // ("$50,000," from "…up to $50,000, except…") and then never match the
    // rewrite, producing a false "missing" on a perfectly good variant.
    add(/\$\s?\d{1,3}(?:,\d{3})*(?:\.\d{1,2})?/g);                       // money
    add(/\b\d+(?:\.\d+)?\s?(?:%|percent)\b/gi);                          // percentages
    // Must END on an alphanumeric. The old [A-Za-z0-9.\-]* swallowed the
    // sentence's trailing period ("Exhibit A." from "…in Exhibit A."), then
    // looked for that exact string in a rewrite that ended differently and
    // reported a false "missing". Same trap as the money regex below.
    add(/\b(?:Section|Article|Exhibit|Schedule|Appendix|Annex|Clause)\s+[A-Za-z0-9](?:[A-Za-z0-9.\-]*[A-Za-z0-9])?/g); // cross-refs
    add(/\b(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},?\s+\d{4}\b/g); // dates
    add(/\b\d{1,3}(?:,\d{3})+\b/g);                                      // thousand-separated numbers
    add(/[“"]([^”"\n]{2,60})[”"]/g, 1);                                  // quoted defined terms (inner text)
    return out;
  }
  function _norm(s) {
    return String(s)
      .replace(/[“”]/g, '"')
      .replace(/[‘’]/g, "'")
      .replace(/\s+/g, " ")
      .trim()
      .toLowerCase();
  }
  // A dropped proviso is the dangerous silent failure (the rewrite reads
  // cleaner precisely because the carve-out is gone). Structural test:
  // original had exception language, rewrite has none at all.
  var EXCEPTION_RE = /\b(provided\s+that|provided,?\s*however|except|unless|excluding|other than|shall not apply|does not apply|save for|subject to|but not)\b/i;

  // Party/role designators. The classic silent drift is a rewrite that reads
  // fine but swaps the document's own vocabulary — "Supplier" becomes
  // "Vendor", "Purchaser" becomes "Buyer". Comparing the variant against the
  // WHOLE DOCUMENT (not just the selection) is the only way to see it.
  var ROLE_TERMS = [
    "Supplier", "Vendor", "Buyer", "Purchaser", "Seller", "Customer", "Client",
    "Contractor", "Subcontractor", "Company", "Licensor", "Licensee", "Lessor",
    "Lessee", "Landlord", "Tenant", "Employer", "Employee", "Consultant",
    "Provider", "Recipient", "Discloser", "Disclosing Party", "Receiving Party",
    "Manufacturer", "Distributor", "Reseller", "Affiliate", "Agreement", "Contract",
  ];
  function _hasWord(hay, word) {
    if (!hay || !word) return false;
    var esc = String(word).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    try { return new RegExp("\\b" + esc + "\\b", "i").test(hay); }
    catch (e) { return hay.indexOf(String(word).toLowerCase()) !== -1; }
  }
  // Terms the rewrite introduced that appear NOWHERE in the document.
  // A term already present in the user's own selection is never "drift" —
  // checking that explicitly also keeps the guard correct when the document
  // read fails or is truncated.
  function _vocabDrift(docText, variant, orig) {
    if (!docText) return [];
    var dn = _norm(docText), vn = _norm(variant), on = _norm(orig || "");
    var out = [];
    ROLE_TERMS.forEach(function (term) {
      var t = _norm(term);
      if (!_hasWord(vn, t)) return;   // not in the rewrite
      if (_hasWord(on, t)) return;    // came from the selection itself
      if (_hasWord(dn, t)) return;    // used elsewhere in the document
      out.push(term);
    });
    return out;
  }

  // Defined terms from the WHOLE document, as ground truth for the prompt.
  // docText was previously read on every run and used only by the drift
  // CHECK — the model never saw it, so it had to guess which capitalised
  // words were defined. Sending a bounded list instead of the document
  // keeps the prompt small and the answer exact.
  function _definedTerms(doc) {
    var d = String(doc || "");
    if (!d) return [];
    var found = {}, out = [];
    function add(t) {
      var v = String(t || "").trim();
      if (v.length < 3 || v.length > 60) return;
      if (!/^[A-Z]/.test(v)) return;
      var k = v.toLowerCase();
      if (found[k]) return;
      found[k] = true;
      out.push(v);
    }
    var re, m;
    // (the "Receiving Party")  /  ("Receiving Party")
    re = /\(\s*(?:the\s+|each\s+|an?\s+)?[“"]([^”"\n]{3,60})[”"]\s*\)/g;
    while ((m = re.exec(d)) !== null) add(m[1]);
    // "Receiving Party" means / shall mean
    re = /[“"]([^”"\n]{3,60})[”"]\s+(?:means|shall mean|has the meaning)/gi;
    while ((m = re.exec(d)) !== null) add(m[1]);
    return out.slice(0, 40);   // bounded — a prompt, not a glossary dump
  }

  function _preservationCheck(orig, variant, docText) {
    var missing = [];
    var vn = _norm(variant);
    var seen = {};
    // Longest first, then drop any token contained in one already kept —
    // otherwise "$50,000" and "50,000" both report the same missing fact.
    var toks = _collect(orig).slice().sort(function (a, b) { return b.length - a.length; });
    var kept = [];
    toks.forEach(function (tok) {
      var key = _norm(tok);
      if (!key || seen[key]) return;
      for (var k = 0; k < kept.length; k++) {
        if (kept[k].indexOf(key) !== -1) return;   // substring of a longer token
      }
      seen[key] = true;
      kept.push(key);
      if (vn.indexOf(key) === -1) missing.push(tok);
    });
    var lostProviso = EXCEPTION_RE.test(orig) && !EXCEPTION_RE.test(variant);
    var introduced = _vocabDrift(docText, variant, orig);
    // Locked phrases must survive character-for-character (whitespace aside).
    var lockBroken = locked.filter(function (ph) {
      return vn.indexOf(_norm(ph)) === -1;
    });
    return {
      ok: missing.length === 0 && !lostProviso && introduced.length === 0 && lockBroken.length === 0,
      missing: missing,
      lostProviso: lostProviso,
      introduced: introduced,
      lockBroken: lockBroken,
    };
  }

  function _words(s) {
    var t = String(s || "").trim();
    return t ? t.split(/\s+/).filter(Boolean).length : 0;
  }

  // ── Prompt ───────────────────────────────────────────────────────────
  // input.only = one register label → regenerate just that card.
  // input.avoid = the version being replaced, so the retry differs.
  // Two registers, not three. "Formal" was dropped: contract prose is
  // already formal, so it returned the smallest delta and what it added
  // ("hereto", extra "shall"s) is what modern drafting removes.
  // Humanised is constrained for legal register — the generic version
  // produces contractions and second person, which are wrong in an
  // operative provision.
  var REGISTERS = [
    ["Polished", "the same passage written well: better flow, no throat-clearing, run-ons split."],
    ["Humanised", "natural sentence rhythm with varied length; strip robotic connectives " +
      "(\"in order to ensure that\", stacked participial openers) and the uniform cadence that " +
      "marks machine-written text. NEVER use contractions, never address the reader as \"you\", " +
      "and never soften or weaken an obligation — this is contract language, not conversation."],
  ];
  var only = String((input && input.only) || "").trim().toLowerCase();
  var avoid = String((input && input.avoid) || "").trim();
  var wanted = only
    ? REGISTERS.filter(function (r) { return r[0].toLowerCase() === only; })
    : REGISTERS;
  if (!wanted.length) wanted = REGISTERS;
  // [MINIMAL] A correction pass over the author's own text, not a register
  // rewrite. It needs its own framing because the register prompt below
  // demands a GENUINE rewrite that restructures sentences — the exact
  // opposite instruction — and a model handed both either restructures
  // (ignoring the request) or returns the text untouched (obeying it).
  //
  // It also needs its own pseudo-register. `only` carries the ACTIVE card's
  // label, and after one minimal pass that label is "Minimal changes", which
  // matches no register — so the filter above emptied, fell back to ALL
  // registers, and a second click silently asked for two full rewrites.
  var minimal = !!(input && input.minimal);
  if (minimal) wanted = [["Minimal changes", "corrected, not rewritten"]];
  var single = wanted.length === 1;

  var prompt =
    (minimal
      ? "You are PROOFREADING a passage from a professional or legal document. " +
        "Correct it once.\n\n"
      : "You are polishing a passage from a professional or legal document. Rewrite it " +
        (single ? "ONCE" : "THREE times") + ".\n\n") +
    "ABSOLUTE RULE — PRESERVE MEANING EXACTLY. Never add, remove, weaken or broaden an obligation, " +
    "condition, exception, carve-out, party, amount, date, defined term or cross-reference. You are " +
    "improving the WRITING, never the substance. Every proviso in the original must survive in all three.\n\n" +
    (minimal
      ? "THIS IS A CORRECTION PASS, NOT A REWRITE. Fix only what is actually wrong: " +
        "typos, misspellings, grammar, subject-verb agreement, punctuation, and plainly " +
        "wrong word choices. Preserve the author's wording, sentence structure, paragraph " +
        "order and voice exactly. Do not restructure, shorten, lengthen, combine or split " +
        "sentences, and do not improve style. Any sentence that is already correct must " +
        "come back UNCHANGED, word for word. If nothing in the passage is wrong, return it " +
        "exactly as given.\n\n"
      : (single ? "Produce ONE version in this register:\n" : "Produce these three registers, in this order:\n") +
        wanted.map(function (r, i) {
          return "  " + (i + 1) + '. "' + r[0] + '" — ' + r[1];
        }).join("\n") + "\n\n") +
    (avoid
      ? ("You produced this before and the user rejected it. Produce a MEANINGFULLY DIFFERENT " +
         "rewrite — not a paraphrase of it:\n\"\"\"\n" + avoid + "\n\"\"\"\n\n")
      : "") +
    (instruction
      ? ("USER INSTRUCTION — apply to all three: " + instruction + "\n\n")
      : "") +
    (locked.length
      ? ("LOCKED PHRASES — these are negotiated wording. Reproduce each one VERBATIM, " +
         "character for character, in every version. Improve the writing AROUND them:\n" +
         locked.map(function (p) { return "  • " + p; }).join("\n") + "\n\n")
      : "") +
    // Emphasis inside the passage has to survive the rewrite, and the only
    // way it can is if the model can see it. Markers in, markers out.
    // Ground truth, not recall. Same reasoning as the section-index block
    // in Error Review: a model asked to remember what is defined will
    // invent, and the failure reads fluently.
    (function () {
      var terms = _definedTerms(docText);
      if (!terms.length) return "";
      return "DEFINED TERMS IN THIS DOCUMENT — these are defined elsewhere in the agreement. " +
        "Reproduce any that appear EXACTLY as written, including capitalisation. Never " +
        "substitute a synonym, never change the case, and never introduce a capitalised term " +
        "that is not on this list:\n  " + terms.join(" · ") + "\n\n";
    })() +
    "FORMATTING MARKERS: the passage may contain **bold**, *italic* and __underlined__ text. " +
    "Keep each marker around the SAME words in your rewrite — they mark defined terms and " +
    "negotiated wording. Never introduce new markers, and never mark text that was not marked. " +
    "If a marked phrase is genuinely rephrased away, drop its markers rather than guessing where " +
    "they belong.\n\n" +
    (minimal
      ? "Keep the same number of paragraphs as the original and separate paragraphs with a " +
        "newline (\\n).\n\n"
      : "Each version must be a GENUINE rewrite — restructure sentences where it helps readability. " +
        "Do not merely swap one or two words. Keep the same number of paragraphs as the original and " +
        "separate paragraphs with a newline (\\n).\n\n") +
    "Return ONLY a JSON array, no markdown:\n" +
    "[" + wanted.map(function (r) {
      return '{"label":"' + r[0] + '","why":"<6 words max on what you changed>","text":"<the rewrite>"}';
    }).join(",") + "]\n\n" +
    "PASSAGE:\n\"\"\"\n" + original + "\n\"\"\"";

  // Writing is not deep reasoning — a small budget keeps Polish snappy.
  var raw = await providers.ai.completeJSON(prompt, null, {
    thinkingBudget: 512,
    strict: true,
    signal: input && input.signal,
  });

  var list = Array.isArray(raw)
    ? raw
    : (raw && Array.isArray(raw.versions) ? raw.versions : []);

  var origWords = _words(original);
  var variantsRaw = list.map(function (v) {
    var text = String((v && v.text) || "").trim();
    return {
      label: String((v && v.label) || "").trim() || "Polished",
      why: String((v && v.why) || "").trim(),
      text: text,
      words: _words(text),
      originalWords: origWords,
      check: _preservationCheck(original, text, docText),
    };
  });

  // A rewrite identical to the input is not a rewrite for the three
  // registers. But "Minimal changes" instructs the model to return correct
  // sentences word for word, so on already-clean text an identical answer is
  // the CORRECT answer. Count them instead of discarding the fact, or the
  // caller cannot tell "nothing needed fixing" from "the model failed".
  var unchangedCount = 0;
  var variants = variantsRaw.filter(function (v) {
    if (!v.text) return false;
    if (_norm(v.text) === _norm(original)) { unchangedCount++; return false; }
    return true;
  });

  var toolVer = "unknown";
  try {
    if (typeof window !== "undefined" && window.eli && window.eli.tools &&
        window.eli.tools._loaded && window.eli.tools._loaded["polish"]) {
      toolVer = window.eli.tools._loaded["polish"].releasedAt || "unknown";
    }
  } catch (e) { /* tolerate */ }

  return {
    items: variants,
    overview: variants.length
      ? variants.length + " polished version(s) of " + origWords + " words."
      : (unchangedCount
        ? "The text came back unchanged — nothing needed correcting."
        : "No usable rewrite was produced."),
    _meta: { original: original, instruction: instruction, unchanged: unchangedCount },
    provenance: {
      kernelVersion: (typeof window !== "undefined" && window.eli) ? window.eli.kernelVersion : "node",
      toolVersion: toolVer,
      promptVersion: "polish@v1",
      model: (typeof window !== "undefined" && window.eli && window.eli.ai &&
              typeof window.eli.ai.getModel === "function") ? window.eli.ai.getModel() : null,
      docHash: (input && input.docHash) || null,
      timestamp: Date.now(),
    },
  };
}

// ─── [EXPLAIN] ────────────────────────────────────────────────────────
// Explain a rewrite: what changed and why, grouped by intent. Structured
// JSON rather than prose — the dialog renders a real list, and a schema
// can't drift the way label-scraping does.
// TO REMOVE: delete this function + the "?" button and onExplain wiring.

engine.polishExplain:
function polishExplain(input, providers) {
  var original = String((input && input.original) || "").trim();
  var revised = String((input && input.revised) || "").trim();
  if (!original || !revised) {
    return Promise.reject(new Error("Nothing to compare."));
  }
  var prompt =
    "Compare two versions of the same passage from a professional or legal document " +
    "and explain the EDITING decisions.\n\n" +
    "ORIGINAL:\n\"\"\"\n" + original + "\n\"\"\"\n\n" +
    "REVISED:\n\"\"\"\n" + revised + "\n\"\"\"\n\n" +
    "Return ONLY JSON:\n" +
    '{"summary":"<one sentence on the overall approach>",' +
    '"edits":[{"kind":"<2-3 word category, e.g. Sentence split, Word choice, Redundancy, Order>",' +
    '"what":"<the specific change, <= 12 words>",' +
    '"why":"<why it improves the writing, <= 22 words>"}]}\n\n' +
    "Rules: 3-6 edits, most significant first. Describe only changes that ACTUALLY differ " +
    "between the two texts — never invent one. If meaning shifted at all, say so plainly in " +
    "that edit's \"why\" and put it first, since that is the one thing the reader must catch. " +
    "Do not praise the rewrite.";
  return providers.ai.completeJSON(prompt, {
    type: "object",
    properties: {
      summary: { type: "string" },
      edits: {
        type: "array",
        items: {
          type: "object",
          properties: { kind: { type: "string" }, what: { type: "string" }, why: { type: "string" } },
          required: ["what"],
        },
      },
    },
    required: ["edits"],
  }, { maxTokens: 700, thinkingBudget: 0 });
}
// ─── [/EXPLAIN] ───────────────────────────────────────────────────────

