          ? newText.filter(function (s) { return s && String(s.text || "").length; })
          : [{ text: String(newText == null ? "" : newText) }];
        if (!segs.length) segs = [{ text: "" }];

        function _fmt(rng, seg) {
          if (!rng) return;
          try {
            // Base font first, then the segment's own emphasis — setting
            // name/size never clears bold/italic/underline.
            if (snap) {
              if (snap.name != null) rng.font.name = snap.name;
              if (snap.size != null) rng.font.size = snap.size;
              if (snap.color != null) rng.font.color = snap.color;
            }
            rng.font.bold = !!seg.bold;
            rng.font.italic = !!seg.italic;
            rng.font.underline = seg.underline ? "Single" : "None";
          } catch (e) { /* formatting is best-effort; the text landed */ }
        }

        var prev = range.insertText(segs[0].text, "Replace");
        _fmt(prev, segs[0]);
        for (var si = 1; si < segs.length; si++) {
          // insertText("") returns undefined on Word for Web — empties are
          // already filtered above, so prev is always a real range here.
          var nxt = prev.insertText(segs[si].text, "After");
          _fmt(nxt, segs[si]);
          prev = nxt || prev;
        }
        await context.sync();
        // ─── [/FMT] ───────────────────────────────────────────────────
      } finally {
        if (prior != null && prior !== target) {
          try {
            context.document.changeTrackingMode = prior;
            await context.sync();
          } catch (e) { /* tolerate */ }
        }
      }
    });
  }

  // Whole-document text for the vocabulary-drift check. Init scope so both
  // the single and batch flows can use it.
  function _docText() {
    try {
      var c = (eli.host && typeof eli.host.cachedText === "function") ? eli.host.cachedText() : null;
      if (c && c.text && !c.stale) return Promise.resolve(String(c.text).slice(0, 120000));
    } catch (e) { /* fall through to a live read */ }
    if (eli.host && typeof eli.host.readText === "function") {
      return eli.host.readText({})
        .then(function (t) { return String(t || "").slice(0, 120000); })
        .catch(function () { return ""; });
    }
    return Promise.resolve("");
  }

  // Select + scroll to a bookmarked paragraph so the user sees where they are.
  function _selectBookmark(name) {
    if (!name) return Promise.resolve();
    return eli.host.runRaw("polish:locate", function (context) {
      var r = context.document.getBookmarkRangeOrNullObject(name);
      r.load("isNullObject");
      return context.sync().then(function () {
        if (r.isNullObject) return null;
        r.select();
        try { r.scrollIntoView(); } catch (e) {}
        return context.sync();
      });
    }).catch(function () { /* navigation is best-effort */ });
  }

  function _notice(host, text) {
    host.innerHTML = "";
    var d = document.createElement("div");
    d.style.cssText = "padding:22px 20px;background:#fff;border:1px solid #e5e7eb;" +
      "font:500 13px/1.65 Inter,'Segoe UI',system-ui,sans-serif;color:#6b7280;";
    d.textContent = text;
    host.appendChild(d);
  }

  function _backFn(cameFromAskEli) {
    if (!cameFromAskEli) return null;
    return function () {
      try {
        var ddr = document.getElementById("_eli3_dashboard_root");
        if (ddr) ddr.style.display = "";
      } catch (e) { /* tolerate */ }
      try { eli.dispatch("tile", "app_ask_eli"); } catch (e) { /* tolerate */ }
    };
  }

  // Batch: scan, show the start screen, then step the flagged paragraphs in
  // DOCUMENT ORDER, inserting as we go so stopping halfway leaves a coherent
  // document. No "polish as one passage" escape at this size — a 12-paragraph
  // single rewrite is exactly the unreviewable blob batch mode exists to avoid.
  function _startBatch(host, allParas, totalWords, cameFromAskEli) {
    var back = _backFn(cameFromAskEli);
    // Selecting the paragraphs IS the decision to review them — every one is
    // queued, in document order. No scoring, nothing skipped silently.
    var flagged = allParas.map(function (p, i) {
      var t = String(p.text || "").trim();
      return { index: i, text: t, words: t ? t.split(/\s+/).filter(Boolean).length : 0 };
    });
    var allItems = flagged;
    // Set by the start screen. The level steer and the focus note are
    // prepended to every paragraph's instruction, so one decision governs
    // the whole run instead of being retyped for each paragraph.
    var _runCfg = { levelSteer: "", focus: "", level: "" };
    // How many paragraphs actually reached the document, so the end
    // screen can report the split rather than just a total.
    var _inserted = 0;
    function _runPrefix() {
      return [_runCfg.levelSteer, _runCfg.focus].filter(Boolean).join(" ");
    }

    function _step(qi){
      if (qi >= flagged.length) {
        if (renderPolishDone) {
          renderPolishDone({
            host: host, total: flagged.length, inserted: _inserted,
            onHome: function () {
              if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
            },
            onBack: back,
          });
        } else {
          _notice(host, "Finished — stepped through all " + flagged.length + " paragraph(s).");
        }
        return;
      }
      var item = flagged[qi];
      var para = allParas[item.index] || {};
      var text = item.text;
      var instr = "", locks = [];
      _selectBookmark(para.bookmark);

      var ui = renderPolishWorkspace({
        host: host,
        original: text,
        wordCount: item.words,
        notices: [],
        progress: { current: qi + 1, total: flagged.length },
        onBack: back,
        onSkip: function () { _step(qi + 1); },
        onExplain: function (orig, revised, label) {        // [EXPLAIN]
          if (!polishExplain) return Promise.reject(new Error("Explain unavailable."));
          return polishExplain({ original: orig, revised: revised, label: label },
            { ai: eli.ai, host: eli.host });
        },
        onUse: function (segs, tracked) {
          return _insert(para.bookmark, _crSegs(segs), tracked, true)
            .then(function () {
              _inserted++;
              try { if (eli.stats) eli.stats.record("polishApplied"); } catch (e) {}
              try { if (eli.host && eli.host.invalidateCache) eli.host.invalidateCache(); } catch (e) {}
              setTimeout(function () { _step(qi + 1); }, 500);
            });
        },
        onRegenerate: function (i2, l2) { instr = i2 || ""; locks = l2 || []; _gen(); },
        onRegenOne: function (label, cur, steer, o) {
          return _docText().then(function (dt) {
            return polishAnalyze({
              text: text,
              instruction: _steered(_steered(_runPrefix(), instr), steer),
              docText: dt, locked: locks,
              only: label, avoid: cur,
              minimal: !!(o && o.minimal),
            }, { ai: eli.ai, host: eli.host });
          }).then(function (r) { return _regenResult(r); });
        },
        onInlineRegen: function (frag, full, mode) {
          if (!polishFragment) return Promise.reject(new Error("Fragment rewrite unavailable."));
          return polishFragment({ fragment: frag, context: full, mode: mode },
            { ai: eli.ai, host: eli.host });
        },
      });

      function _gen() {
        ui.setBusy(true, "Polishing…");
        _docText().then(function (dt) {
          return polishAnalyze({
            text: text, instruction: _steered(_runPrefix(), instr),
            docText: dt, locked: locks,
          }, { ai: eli.ai, host: eli.host });
        }).then(function (r) {
          ui.setBusy(false);
          ui.setVariants((r && r.items) || []);
        }).catch(function (err) {
          ui.setBusy(false);
          ui.setVariants([]);
          if (typeof showToast === "function") {
            showToast("Polish failed: " + ((err && err.message) || "unknown"), "err");
          }
        });
      }
      _gen();
    }

    renderPolishBatchStart({
      host: host,
      total: allParas.length,
      words: totalWords,
      items: allItems,                                   // every selected paragraph
      onBack: back,
      onStart: function (cfg) {
        cfg = cfg || {};
        _runCfg.levelSteer = cfg.levelSteer || "";
        _runCfg.level = cfg.level || "";
        _runCfg.focus = cfg.focus ? ("Pay particular attention to: " + cfg.focus) : "";
        // Rebuild the queue from the tick boxes. flagged drives both the
        // step order and the "N of M" counter, so filtering here keeps
        // every downstream count honest.
        if (cfg.include && cfg.include.length && cfg.include.length !== flagged.length) {
          var keep = {};
          cfg.include.forEach(function (i) { keep[i] = true; });
          flagged = flagged.filter(function (it, i) { return keep[i]; });
        }
        _step(0);
      },
    });
  }

  // openCtx.from identifies the caller. Only the Ask ELI panel gets a
  // "back" path — opening from the dashboard has nowhere to return to.
  async function showPolish(openCtx) {
    if (_busy) return;
    var cameFromAskEli = !!(openCtx && openCtx.from === "ask_eli");
    // Announce the tool. The kernel fires tool:open on a TILE click, but
    // Polish is usually reached by dispatch from Ask ELI — and ask_dock
    // gates its chevron on that event, so without this the Ask ELI
    // pull-down never appears here.
    try { if (eli.bus) eli.bus.emit("tool:open", { id: "polish" }); } catch (e) { /* tolerate */ }
    var host = (eli.ui && typeof eli.ui.claimOutput === "function")
      ? eli.ui.claimOutput()
      : document.getElementById("output");
    if (!host) return;

    var sel = null;
    try { sel = await _readSelection(); } catch (e) { sel = null; }
    if (!sel || !String(sel.text || "").trim()) {
      _notice(host, "Select the text you want to polish in the document, then click Polish again.");
      return;
    }

    // Word uses \r for paragraph marks; normalise for display + the AI, and
    // convert back on insert so paragraph breaks survive the round trip.
    var original = String(sel.text).replace(/\r\n?/g, "\n").trim();
    var wordCount = original.split(/\s+/).filter(Boolean).length;

    // More than one paragraph → batch. A single paragraph is one thought and
    // goes straight to the workspace.
    var allParas = (sel.paragraphs || []).filter(function (p) { return p.text; });
    if (allParas.length > 1 && renderPolishBatchStart) {
      return _startBatch(host, allParas, wordCount, cameFromAskEli);
    }

    // Current instruction/locks, so a single-card regen matches the others.
    var _lastInstruction = "";
    var _lastLocked = [];

    var notices = [];
    if (sel.hadRedlines) {
      notices.push({ kind: "info", text: "This selection has pending tracked changes — polishing the accepted (post-change) text." });
    }
    if (sel.isList) {
      notices.push({ kind: "warn", text: "Selection sits in an automatic list. Inserting replaces the text only; check numbering afterwards, especially for multi-paragraph rewrites." });
    }

    var ui = renderPolishWorkspace({
      host: host,
      original: original,
      wordCount: wordCount,
      notices: notices,
      heading: sel.heading || null,   // [FMT] re-attached verbatim on insert
      onExplain: function (orig, revised, label) {        // [EXPLAIN]
        if (!polishExplain) return Promise.reject(new Error("Explain unavailable."));
        return polishExplain({ original: orig, revised: revised, label: label },
          { ai: eli.ai, host: eli.host });
      },
      onBack: cameFromAskEli ? function () {
        // claimOutput() hid the dashboard root on the way in; Ask ELI mounts
        // into it, so un-hide before reopening or it renders invisibly.
        try {
          var ddr = document.getElementById("_eli3_dashboard_root");
          if (ddr) ddr.style.display = "";
        } catch (e) { /* tolerate */ }
        try { eli.dispatch("tile", "app_ask_eli"); } catch (e) { /* tolerate */ }
      } : null,
      onUse: function (segs, tracked) {
        return _insert(sel.bookmark, _crSegs(segs), tracked).then(function () {
          try { if (eli.stats) eli.stats.record("polishApplied"); } catch (e) {}
          try {
            if (eli.activity && typeof eli.activity.add === "function") {
              eli.activity.add({
                type: "polish", icon: "✨", label: "Polish applied",
                summary: wordCount + " words rewritten" + (tracked ? " (tracked)" : ""),
                timestamp: Date.now(),
              });
            }
          } catch (e) {}
          try { if (eli.host && typeof eli.host.invalidateCache === "function") eli.host.invalidateCache(); } catch (e) {}
        });
      },
      onRegenerate: function (instruction, locked) { _run(instruction, locked); },
      // Regenerate ONE register, reusing the instruction/locks currently in
      // effect, and telling the model what it produced last so the retry
      // differs rather than paraphrasing itself.
      onRegenOne: function (label, currentText, steer, o) {
        return _docText().then(function (docText) {
          return polishAnalyze(
            {
              text: original,
              instruction: _steered(_lastInstruction, steer),
              docText: docText,
              locked: _lastLocked,
              only: label,
              avoid: currentText,
              minimal: !!(o && o.minimal),
            },
            { ai: eli.ai, host: eli.host }
          );
        }).then(function (res) { return _regenResult(res); });
      },
      // Highlight-to-regen inside a version: rewrite just that fragment,
      // with the full version supplied as context.
      onInlineRegen: function (fragment, fullText, mode) {
        if (!polishFragment) return Promise.reject(new Error("Fragment rewrite unavailable."));
        return polishFragment(
          { fragment: fragment, context: fullText, mode: mode },
          { ai: eli.ai, host: eli.host }
        );
      },
    });

    function _run(instruction, locked) {
      _lastInstruction = instruction || "";
      _lastLocked = locked || [];
      _busy = true;
      ui.setBusy(true, "Polishing…");
      Promise.resolve()
        .then(function () { return _docText(); })
        .then(function (docText) {
          return polishAnalyze(
            {
              text: original,
              instruction: instruction,
              docText: docText,
              locked: locked || [],
            },
            { ai: eli.ai, host: eli.host }
          );
        })
        .then(function (res) {
          ui.setBusy(false);
          ui.setVariants((res && res.items) || []);
        })
        .catch(function (err) {
          ui.setBusy(false);
          ui.setVariants([]);
          if (typeof showToast === "function") {
            showToast("Polish failed: " + ((err && err.message) || "unknown"), "err");
          }
        })
        .then(function () { _busy = false; });
    }

    _run("");
  }

  eli.register({
    tile: { app_polish: showPolish },
    // Cross-tool entry point — Ask ELI's "Polish Text" button dispatches this.
    polish: {
      open: showPolish,
      // Rewrite ONE highlighted fragment in place. Build Draft's Enhance box
      // calls this so ELI keeps a single fragment-rewrite prompt rather than
      // one per tool that happens to have an editable field.
      fragment: function (frag, full, mode) {
        if (!polishFragment) return Promise.reject(new Error("Fragment rewrite unavailable."));
        return polishFragment({ fragment: frag, context: full, mode: mode },
          { ai: eli.ai, host: eli.host });
      },
    },
  });
}

jsonTools.css:
/* tools/polish/style.css — states that cannot be inlined (:hover/:focus,
   keyframes, diff spans). Layout + colour live inline for guaranteed paint. */

._pl_root ._pl_card {
  transition: box-shadow .16s ease, transform .16s ease;
}
._pl_root ._pl_card:hover {
  box-shadow: 0 1px 2px rgba(15, 23, 42, .05), 0 14px 30px rgba(15, 23, 42, .085);
  transform: translateY(-1px);
}
._pl_root ._pl_prose:hover {
  background: #fbfcfd;
  border-color: #e9ecf1 !important;
}
._pl_root ._pl_prose:focus {
  background: #ffffff;
  border-color: #c9a227 !important;
  box-shadow: 0 0 0 3px rgba(201, 162, 39, .13);
}
._pl_root ._pl_instr:focus {
  background: #ffffff !important;
  border-color: #c9a227 !important;
  box-shadow: 0 0 0 3px rgba(201, 162, 39, .11);
}
._pl_root ._pl_del {
  color: #b3261e;
  text-decoration: line-through;
  text-decoration-thickness: 1px;
}
._pl_root ._pl_add {
  color: #146c43;
  text-decoration: underline;
  text-decoration-thickness: 1px;
}
._pl_root ._pl_menuitem:hover {
  background: #1f2a3a !important;
  filter: none;
}
._pl_root button:not(:disabled):hover {
  filter: brightness(1.03);
}
._pl_root button:not(:disabled):active {
  transform: translateY(1px);
}
._pl_root button:disabled {
  opacity: .62;
  cursor: default;
}
@keyframes _plPulse {
  0%, 100% { opacity: .42; }
  50%      { opacity: .82; }
}

/* ─── [THINKING] ────────────────────────────────────────────────────── */
/* A regenerate can take a few seconds. "…" in the button was too quiet   */
/* to read as working, so the TEXT ITSELF shimmers — the thinking is      */
/* shown where the change will land, not off to one side.                */
/* TO REMOVE: delete this block + the [THINKING] blocks in view.js.       */
@keyframes _pl_shimmer {
  0%   { background-position: 220% 0; }
  100% { background-position: -220% 0; }
}
._pl_thinking {
  background-image: linear-gradient(
    100deg,
    rgba(99, 102, 241, 0.00) 20%,
    rgba(99, 102, 241, 0.20) 42%,
    rgba(168, 85, 247, 0.26) 52%,
    rgba(99, 102, 241, 0.20) 62%,
    rgba(99, 102, 241, 0.00) 84%
  );
  background-size: 220% 100%;
  background-repeat: no-repeat;
  animation: _pl_shimmer 1.25s linear infinite;
  border-radius: 3px;
  box-shadow: 0 0 0 1px rgba(99, 102, 241, 0.18);
}
/* Whole-card variant — same sweep, calmer, plus a dimmed body. */
._pl_thinking_block {
  animation: _pl_shimmer 1.6s linear infinite;
  background-image: linear-gradient(
    100deg,
    rgba(99, 102, 241, 0.00) 25%,
    rgba(99, 102, 241, 0.13) 50%,
    rgba(99, 102, 241, 0.00) 75%
  );
  background-size: 220% 100%;
  background-repeat: no-repeat;
  color: rgba(31, 41, 55, 0.45);
}
@keyframes _pl_spin { to { transform: rotate(360deg); } }
._pl_spin { display: inline-block; animation: _pl_spin .85s linear infinite; }

@media (prefers-reduced-motion: reduce) {
  ._pl_thinking, ._pl_thinking_block, ._pl_spin { animation: none !important; }
  ._pl_thinking { box-shadow: 0 0 0 1px rgba(99, 102, 241, 0.35); }
}
/* ─── [/THINKING] ───────────────────────────────────────────────────── */
